<script setup lang="ts">
import { computed, ref } from 'vue';
import { PhWallet, PhCopy, PhCheckCircle, PhArrowUpRight, PhPlugs, PhCoins } from '@phosphor-icons/vue';
import { useBallot } from '../store';
import { localTestAccounts } from '../local-test-accounts';

const store = useBallot();
const accountIndex = ref('1');
const testAccount = computed(() => localTestAccounts.find(account => account.index === Number(accountIndex.value))!);
async function copy(value: string) {
  try { await navigator.clipboard.writeText(value); store.notify('Copied to clipboard.', 'success'); }
  catch { store.notify('Select and copy the displayed value.', 'info'); }
}
</script>

<template>
  <div class="page-heading"><div><div class="eyebrow"><span class="tiny-line"></span>Your connection to the ballot</div><h1>MetaMask setup</h1><p>Your keys stay in your wallet. Every vote starts with your confirmation.</p></div><div class="page-symbol"><PhWallet :size="32" /></div></div>
  <div class="wallet-setup-status" :class="{ 'wallet-not-detected': !store.metaMaskAvailable }"><PhCheckCircle v-if="store.address || store.metaMaskAvailable" :size="21" /><PhPlugs v-else :size="21" /><span>{{ store.address ? 'MetaMask connected' : store.metaMaskAvailable ? 'MetaMask detected in this browser' : 'MetaMask has not been detected in this browser' }}</span><span class="wallet-status-note">{{ store.address ? 'Wallet authorized' : store.metaMaskAvailable ? 'Ready to connect' : 'Complete the steps below' }}</span></div>
  <div class="wallet-setup-grid">
    <section class="form-panel wallet-setup-card"><h2>1. Open a browser with MetaMask</h2><p>Use a browser with the MetaMask extension installed and unlocked. If MetaMask is unavailable in the current browser, open the same local app URL in your MetaMask-enabled browser.</p><a class="text-button" href="https://metamask.io/download/" target="_blank" rel="noopener noreferrer">Get MetaMask<PhArrowUpRight :size="16" /></a><h2>2. Connect the voting network</h2><p>Select Connect MetaMask. The wallet will request account access and, when needed, ask you to switch or add the voting network. Sign the login message to prove wallet ownership.</p><dl class="setup-network"><div><dt>Network</dt><dd>{{ store.config?.chainId === 31337 ? 'Hardhat Local' : 'Ethereum Sepolia' }}</dd></div><div><dt>Chain ID</dt><dd>{{ store.config?.chainId }}</dd></div><template v-if="store.config?.chainId === 31337"><div><dt>RPC URL</dt><dd><code>http://127.0.0.1:8545</code></dd></div><div><dt>Gas currency</dt><dd>ETH</dd></div></template></dl><button class="button" :disabled="store.busy || store.walletLoading || !store.config" @click="store.connectMetaMask">{{ store.walletLoading ? 'Connecting…' : 'Connect MetaMask' }}<PhWallet :size="18" /></button></section>
    <section v-if="store.config?.demoEnabled && store.config.chainId === 31337" class="form-panel wallet-setup-card"><h2>3. Import a local test account</h2><p>For the seeded elections, import a public Hardhat test key into MetaMask. Voter 01 and Voter 02 have test ETH, VOTE Tokens, and an unused vote in Campus improvement fund.</p><label class="field-label">Test account to import<select v-model="accountIndex" aria-label="Test account to import"><option v-for="account in localTestAccounts" :key="account.index" :value="String(account.index)">{{ account.label }}</option></select></label><div class="setup-account"><span>ACCOUNT ADDRESS</span><code>{{ testAccount.address }}</code><span>PUBLIC LOCAL TEST PRIVATE KEY</span><code>{{ testAccount.privateKey }}</code><button class="text-button" @click="copy(testAccount.privateKey)"><PhCopy :size="16" />Copy test private key</button></div><p class="setup-key-note">These keys are publicly known and intended only for Hardhat Local. Never send real funds to these accounts. The app never uses these keys to sign your transactions.</p><p>In MetaMask, import the key using its account import action, select that account, then connect it to this app. Changing the selector above only displays an import reference; it does not switch your wallet.</p></section>
    <section v-if="store.config?.chainId === 11155111" class="form-panel wallet-setup-card"><h2>3. Add Tom Token to MetaMask</h2><p>Each successful vote burns {{ store.voteCostLabel }}. Your wallet needs TOM and Sepolia ETH for Gas.</p><div class="setup-account"><span>TOM TOKEN CONTRACT</span><code>{{ store.config.tokenAddress }}</code></div><p>In MetaMask, import a custom Token using this address, symbol TOM, and 18 decimals. The administrator must add your wallet to the election’s eligible voter list before voting.</p><a :href="`https://sepolia.etherscan.io/token/${store.config.tokenAddress}`" target="_blank" rel="noopener noreferrer" class="text-button">View Tom Token<PhArrowUpRight :size="16" /></a></section>
  </div>
  <section class="form-panel wallet-voting-guide"><div class="voting-guide-intro"><span class="step-icon"><PhCoins :size="24" /></span><h2>4. Confirm your vote in MetaMask</h2><p>One confirmed vote.<br>{{ store.voteCostLabel }} burned.</p><RouterLink to="/" class="text-button">Go to elections<PhArrowUpRight :size="16" /></RouterLink></div><div><ol><li>Open an active election and choose a candidate.</li><li>Select Cast vote. If allowance is insufficient, MetaMask requests an approval for exactly {{ store.voteCostLabel }}.</li><li>After approval, MetaMask requests confirmation for the voting transaction.</li><li>A successful vote burns {{ store.voteCostLabel }}. The app displays the updated balance and transaction receipt.</li></ol><p>Rejecting either request in MetaMask does not burn Tokens. A previously confirmed approval remains available. ETH Gas is paid separately.</p></div></section>
</template>
